// Explicit conditional request, when you keep the copy yourself
actor FeedStore {
  private var etag: String?
  private var cached: [Post] = []

  func load(using session: URLSession) async throws -> [Post] {
    var request = URLRequest(url: URL(string: "https://api.example.com/feed")!)
    request.cachePolicy = .reloadIgnoringLocalCacheData   // we do the validation
    if let etag {
      request.setValue(etag, forHTTPHeaderField: "If-None-Match")
    }

    let (data, response) = try await session.data(for: request)
    guard let http = response as? HTTPURLResponse else { throw URLError(.badServerResponse) }

    if http.statusCode == 304 { return cached }           // body was not re-sent
    guard http.statusCode == 200 else { throw APIError.status(http.statusCode) }

    etag = http.value(forHTTPHeaderField: "ETag")
    cached = try JSONDecoder().decode([Post].self, from: data)
    return cached
  }
}

func withRetry<T>(
  attempts: Int = 3,
  base: Duration = .milliseconds(300),
  isRetryable: (Error) -> Bool = APIError.isTransient,
  operation: () async throws -> T
) async throws -> T {
  var attempt = 1
  while true {
    do {
      return try await operation()
    } catch {
      guard attempt < attempts, isRetryable(error) else { throw error }
      let backoff = base * Int(pow(2.0, Double(attempt - 1)))
      let jitter = Duration.milliseconds(Int.random(in: 0...250))
      try await Task.sleep(for: backoff + jitter)   // throws if cancelled
      attempt += 1
    }
  }
}

enum APIError: Error {
  case status(Int)

  static func isTransient(_ error: Error) -> Bool {
    if let urlError = error as? URLError {
      return [.timedOut, .networkConnectionLost, .cannotConnectToHost].contains(urlError.code)
    }
    if let apiError = error as? APIError, case let .status(code) = apiError {
      return code == 429 || (500...599).contains(code)
    }
    return false
  }
}

