final class Connectivity {
  private(set) var isOnline = true
  private let monitor = NWPathMonitor()

  init() {
    monitor.pathUpdateHandler = { [weak self] path in
      Task { @MainActor in self?.isOnline = path.status == .satisfied }
    }
    monitor.start(queue: DispatchQueue(label: "connectivity"))
  }
}

final class Downloader: NSObject, URLSessionDownloadDelegate {
  static let shared = Downloader()
  var backgroundCompletion: (() -> Void)?

  private lazy var session: URLSession = {
    let config = URLSessionConfiguration.background(withIdentifier: "com.example.downloads")
    config.isDiscretionary = false
    config.sessionSendsLaunchEvents = true
    return URLSession(configuration: config, delegate: self, delegateQueue: nil)
  }()

  func start(_ url: URL) {
    session.downloadTask(with: url).resume()
  }

  func urlSession(_ session: URLSession,
                  downloadTask: URLSessionDownloadTask,
                  didFinishDownloadingTo location: URL) {
    // Must move it here — the file is gone when this returns
    let destination = URL.documentsDirectory.appending(path: location.lastPathComponent)
    try? FileManager.default.moveItem(at: location, to: destination)
  }

  func urlSessionDidFinishEvents(forBackgroundURLSession session: URLSession) {
    DispatchQueue.main.async { self.backgroundCompletion?(); self.backgroundCompletion = nil }
  }
}

// AppDelegate: keep the handler so the system knows when you are done
func application(_ app: UIApplication,
                 handleEventsForBackgroundURLSession identifier: String,
                 completionHandler: @escaping () -> Void) {
  Downloader.shared.backgroundCompletion = completionHandler
}

final class PriceSocket {
  private let session: URLSession
  private var task: URLSessionWebSocketTask?

  init(session: URLSession = .shared) { self.session = session }

  func messages(url: URL) -> AsyncThrowingStream<String, Error> {
    let task = session.webSocketTask(with: url)
    self.task = task
    task.resume()

    return AsyncThrowingStream { continuation in
      let reader = Task {
        do {
          while !Task.isCancelled {
            switch try await task.receive() {
            case .string(let text): continuation.yield(text)
            case .data(let data): continuation.yield(String(decoding: data, as: UTF8.self))
            @unknown default: break
            }
          }
          continuation.finish()
        } catch {
          continuation.finish(throwing: error)   // caller reconnects with backoff
        }
      }
      continuation.onTermination = { _ in
        reader.cancel()
        task.cancel(with: .goingAway, reason: nil)
      }
    }
  }

  func subscribe(_ symbol: String) async throws {
    try await task?.send(.string("{\"subscribe\":\"\(symbol)\"}"))
  }

  func ping() { task?.sendPing { _ in } }
}

final class StubURLProtocol: URLProtocol {
  nonisolated(unsafe) static var handler: ((URLRequest) throws -> (HTTPURLResponse, Data))?

  override class func canInit(with request: URLRequest) -> Bool { true }
  override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }
  override func stopLoading() {}

  override func startLoading() {
    guard let handler = Self.handler else {
      client?.urlProtocol(self, didFailWithError: URLError(.unsupportedURL))
      return
    }
    do {
      let (response, data) = try handler(request)
      client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
      client?.urlProtocol(self, didLoad: data)
      client?.urlProtocolDidFinishLoading(self)
    } catch {
      client?.urlProtocol(self, didFailWithError: error)
    }
  }
}

@Test func mapsServerErrorToAPIError() async throws {
  let config = URLSessionConfiguration.ephemeral      // fresh per test
  config.protocolClasses = [StubURLProtocol.self]
  StubURLProtocol.handler = { request in
    let response = HTTPURLResponse(url: request.url!, statusCode: 500,
                                   httpVersion: nil, headerFields: nil)!
    return (response, Data())
  }

  let client = APIClient(session: URLSession(configuration: config))
  await #expect(throws: APIError.status(500)) { try await client.feed() }
}
